//! `time.ParseDuration`, `Duration.String` and `strconv.ParseFloat` (decimal, hex and the special
//! values), with Go's error behaviour. First written for the observer's configuration (its
//! `interval`, `poll_timeout` ...), shared since R1-55; each is checked against the real Go
//! functions by `tests/golden/obs_config.json` (generated by `tools/gen_golden/observer_gen.go`).
//! (Layout note, R2-135: the duration half and the float half would be better in `gostd::time` and
//! `gostd::strconv`; not moved yet: a pure path move of importers in `unifiprotect`, `ipc`,
//! `process` and `wsmedia`, open since R2-135 / R3A-9.)

const NS: u64 = 1;
const US: u64 = 1_000;
const MS: u64 = 1_000_000;
const SEC: u64 = 1_000_000_000;
const MIN: u64 = 60 * SEC;
const HOUR: u64 = 60 * MIN;

/// `time.quote`: ASCII printable as is (`"` and `\` escaped), everything else as `\xNN` per UTF-8 byte.
fn time_quote(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        if (c as u32) >= 0x80 || (c as u32) < 0x20 {
            let mut b = [0u8; 4];
            for byte in c.encode_utf8(&mut b).bytes() {
                out.push_str(&format!("\\x{byte:02x}"));
            }
        } else {
            if c == '"' || c == '\\' {
                out.push('\\');
            }
            out.push(c);
        }
    }
    out.push('"');
    out
}

fn unit_of(u: &str) -> Option<u64> {
    Some(match u {
        "ns" => NS,
        "us" | "\u{b5}s" | "\u{3bc}s" => US,
        "ms" => MS,
        "s" => SEC,
        "m" => MIN,
        "h" => HOUR,
        _ => return None,
    })
}

/// `time.ParseDuration`: nanoseconds, or Go's error text.
pub fn parse_duration(orig: &str) -> Result<i64, String> {
    let invalid = || format!("time: invalid duration {}", time_quote(orig));
    let mut s = orig;
    let mut neg = false;
    if let Some(c) = s.chars().next() {
        if c == '-' || c == '+' {
            neg = c == '-';
            s = &s[1..];
        }
    }
    if s == "0" {
        return Ok(0);
    }
    if s.is_empty() {
        return Err(invalid());
    }
    const LIM: u64 = 1 << 63;
    let mut d: u64 = 0;
    while !s.is_empty() {
        let b = s.as_bytes();
        if !(b[0] == b'.' || b[0].is_ascii_digit()) {
            return Err(invalid());
        }
        // leadingInt
        let before = s.len();
        let mut v: u64 = 0;
        let mut i = 0;
        while i < b.len() && b[i].is_ascii_digit() {
            if v > LIM / 10 {
                return Err(invalid());
            }
            v = v * 10 + u64::from(b[i] - b'0');
            if v > LIM {
                return Err(invalid());
            }
            i += 1;
        }
        s = &s[i..];
        let pre = before != s.len();
        let mut f: u64 = 0;
        let mut scale: f64 = 1.0;
        let mut post = false;
        if s.starts_with('.') {
            s = &s[1..];
            let pl = s.len();
            // leadingFraction
            let b = s.as_bytes();
            let mut j = 0;
            let mut overflow = false;
            while j < b.len() && b[j].is_ascii_digit() {
                if !overflow {
                    if f > (LIM - 1) / 10 {
                        overflow = true;
                    } else {
                        let y = f * 10 + u64::from(b[j] - b'0');
                        if y > LIM {
                            overflow = true;
                        } else {
                            f = y;
                            scale *= 10.0;
                        }
                    }
                }
                j += 1;
            }
            s = &s[j..];
            post = pl != s.len();
        }
        if !pre && !post {
            return Err(invalid());
        }
        let b = s.as_bytes();
        let mut i = 0;
        while i < b.len() && !(b[i] == b'.' || b[i].is_ascii_digit()) {
            i += 1;
        }
        if i == 0 {
            return Err(format!(
                "time: missing unit in duration {}",
                time_quote(orig)
            ));
        }
        let u = &s[..i];
        s = &s[i..];
        let Some(unit) = unit_of(u) else {
            return Err(format!(
                "time: unknown unit {} in duration {}",
                time_quote(u),
                time_quote(orig)
            ));
        };
        if v > LIM / unit {
            return Err(invalid());
        }
        v *= unit;
        if f > 0 {
            v += (f as f64 * (unit as f64 / scale)) as u64;
            if v > LIM {
                return Err(invalid());
            }
        }
        // Go's uint64 addition wraps (two terms of 2^63 make 0); so do both build profiles here
        d = d.wrapping_add(v);
        if d > LIM {
            return Err(invalid());
        }
    }
    if neg {
        return Ok((d as i128).wrapping_neg() as i64);
    }
    if d > (LIM - 1) {
        return Err(invalid());
    }
    Ok(d as i64)
}

fn fmt_frac(v: u64, prec: u32) -> (String, u64) {
    // prints the fraction of v/10**prec without trailing zeros; returns (".xyz" or "", v/10**prec)
    let mut digits = String::new();
    let mut print = false;
    let mut v = v;
    for _ in 0..prec {
        let digit = v % 10;
        print = print || digit != 0;
        if print {
            digits.insert(0, (b'0' + digit as u8) as char);
        }
        v /= 10;
    }
    if print {
        digits.insert(0, '.');
    }
    (digits, v)
}

/// `Duration.String()` of a `std::time::Duration`.
pub fn duration_string_of(d: std::time::Duration) -> String {
    duration_string(i64::try_from(d.as_nanos()).unwrap_or(i64::MAX))
}

/// `Duration.String()` of a nanosecond count.
pub fn duration_string(d: i64) -> String {
    let neg = d < 0;
    let mut u = if neg {
        (d as i128).unsigned_abs() as u64
    } else {
        d as u64
    };
    let mut out;
    if u < SEC {
        if u == 0 {
            return "0s".to_string();
        }
        let (prec, unit) = if u < US {
            (0, "ns")
        } else if u < MS {
            (3, "\u{b5}s")
        } else {
            (6, "ms")
        };
        let (frac, whole) = fmt_frac(u, prec);
        out = format!("{whole}{frac}{unit}");
    } else {
        let (frac, secs) = fmt_frac(u, 9);
        u = secs;
        out = format!("{}{frac}s", u % 60);
        u /= 60;
        if u > 0 {
            out = format!("{}m{out}", u % 60);
            u /= 60;
            if u > 0 {
                out = format!("{u}h{out}");
            }
        }
    }
    if neg {
        out.insert(0, '-');
    }
    out
}

/// `underscoreOK` of strconv: underscores only between digits, or between a base prefix and a digit.
fn underscore_ok(s: &str) -> bool {
    let mut b = s.as_bytes();
    let mut saw = b'^';
    let mut i = 0;
    if !b.is_empty() && (b[0] == b'-' || b[0] == b'+') {
        b = &b[1..];
    }
    let mut hex = false;
    if b.len() >= 2 && b[0] == b'0' && matches!(b[1] | 0x20, b'b' | b'o' | b'x') {
        i = 2;
        saw = b'0';
        hex = (b[1] | 0x20) == b'x';
    }
    while i < b.len() {
        let c = b[i];
        if c.is_ascii_digit() || (hex && matches!(c | 0x20, b'a'..=b'f')) {
            saw = b'0';
        } else if c == b'_' {
            if saw != b'0' {
                return false;
            }
            saw = b'_';
        } else {
            if saw == b'_' {
                return false;
            }
            saw = b'!';
        }
        i += 1;
    }
    saw != b'_'
}

/// `strconv.ParseFloat(s, 64)` for the spellings that matter here: decimal with an optional
/// exponent, underscores as Go allows them, `inf`/`infinity`/`nan` in any case, and hexadecimal
/// floats (`0x1p-2`). A result outside float64's range is Go's "value out of range" error, so
/// `None`.
pub fn parse_float(s: &str) -> Option<f64> {
    let (neg, body) = match s.as_bytes().first() {
        Some(b'+') => (false, &s[1..]),
        Some(b'-') => (true, &s[1..]),
        _ => (false, s),
    };
    let lower = body.to_ascii_lowercase();
    let signed = |f: f64| if neg { -f } else { f };
    match lower.as_str() {
        "inf" | "infinity" => return Some(signed(f64::INFINITY)),
        // a sign is allowed on infinity only
        "nan" => {
            return if s.len() == body.len() {
                Some(f64::NAN)
            } else {
                None
            }
        }
        _ => {}
    }
    if body.is_empty() {
        return None;
    }
    let has_us = body.contains('_');
    if has_us && !underscore_ok(s) {
        return None;
    }
    let clean: String = body.chars().filter(|&c| c != '_').collect();
    let lc = clean.to_ascii_lowercase();
    if let Some(hexpart) = lc.strip_prefix("0x") {
        return parse_hex_float(hexpart).map(signed);
    }
    // decimal: digits [. digits] [e [+-] digits], with at least one mantissa digit
    let b = lc.as_bytes();
    let mut i = 0;
    let mut nd = 0;
    while i < b.len() && b[i].is_ascii_digit() {
        i += 1;
        nd += 1;
    }
    if i < b.len() && b[i] == b'.' {
        i += 1;
        while i < b.len() && b[i].is_ascii_digit() {
            i += 1;
            nd += 1;
        }
    }
    if nd == 0 {
        return None;
    }
    if i < b.len() && b[i] == b'e' {
        i += 1;
        if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
            i += 1;
        }
        let es = i;
        while i < b.len() && b[i].is_ascii_digit() {
            i += 1;
        }
        if es == i {
            return None;
        }
    }
    if i != b.len() {
        return None;
    }
    let f: f64 = lc.parse().ok()?;
    if f.is_infinite() {
        return None;
    }
    Some(signed(f))
}

/// A hexadecimal float literal (`0x1.8p3` without the `0x`). A LIMIT, not Go's exact algorithm
/// (R2-64, PARITY 422): the mantissa is accumulated in `f64` and scaled with `powi`, so a mantissa
/// of more than 53 bits can round twice, a subnormal result can lose bits, and an exponent that
/// does not fit an `i32` is refused where Go caps it. Reachable only from a hex-float `interval`.
fn parse_hex_float(s: &str) -> Option<f64> {
    // mantissa hex digits with an optional '.', then a mandatory p exponent
    let (mant, exp) = s.split_once('p')?;
    let exp: i32 = exp.parse().ok()?;
    let (ip, fp) = match mant.split_once('.') {
        Some((a, b)) => (a, b),
        None => (mant, ""),
    };
    if ip.is_empty() && fp.is_empty() {
        return None;
    }
    let mut v = 0.0f64;
    for c in ip.chars() {
        v = v * 16.0 + f64::from(c.to_digit(16)?);
    }
    let mut scale = 1.0 / 16.0;
    for c in fp.chars() {
        v += f64::from(c.to_digit(16)?) * scale;
        scale /= 16.0;
    }
    let f = v * 2f64.powi(exp);
    if f.is_infinite() {
        None
    } else {
        Some(f)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn durations_parse_and_print_like_go() {
        for (s, want) in [
            ("1s", Some(1_000_000_000)),
            ("0", Some(0)),
            ("+0", Some(0)),
            ("-1s", Some(-1_000_000_000)),
            ("1.5h", Some(5_400_000_000_000)),
            ("1\u{b5}s", Some(1000)),
            ("1\u{3bc}s", Some(1000)),
            ("1us", Some(1000)),
            (".5s", Some(500_000_000)),
            ("1.s", Some(1_000_000_000)),
            ("5", None),
            ("1x", None),
            ("", None),
            (".s", None),
            ("100000000h", None),
            ("9223372036854775807ns", Some(i64::MAX)),
            ("9223372036854775808ns", None),
        ] {
            assert_eq!(parse_duration(s).ok(), want, "{s:?}");
        }
        assert_eq!(
            parse_duration("5").unwrap_err(),
            "time: missing unit in duration \"5\""
        );
        assert_eq!(
            parse_duration("1x").unwrap_err(),
            "time: unknown unit \"x\" in duration \"1x\""
        );
        for (d, want) in [
            (0, "0s"),
            (1_000_000_000, "1s"),
            (250_000_000, "250ms"),
            (-1_000_000_000, "-1s"),
            (90_000_000_000, "1m30s"),
            (7_200_000_000_000, "2h0m0s"),
            (1500, "1.5\u{b5}s"),
            (1, "1ns"),
            (i64::MAX, "2562047h47m16.854775807s"),
        ] {
            assert_eq!(duration_string(d), want, "{d}");
        }
    }

    // R1-113: two terms of 2^63 ns wrap to 0 in Go's uint64 arithmetic (no panic in a debug
    // build, no different answer in a release one)
    #[test]
    fn a_duration_sum_that_overflows_wraps_like_go() {
        assert_eq!(
            parse_duration("9223372036854775808ns9223372036854775808ns"),
            Ok(0)
        );
    }

    #[test]
    fn floats_parse_like_go() {
        assert_eq!(parse_float("1_0"), Some(10.0));
        assert_eq!(parse_float("0x1p-2"), Some(0.25));
        assert_eq!(parse_float("0x10"), None);
        assert_eq!(parse_float("1__0"), None);
        assert_eq!(parse_float(" 2"), None);
        assert_eq!(parse_float("1e400"), None);
        assert_eq!(parse_float(".5"), Some(0.5));
        assert_eq!(parse_float("5."), Some(5.0));
        assert_eq!(parse_float("+2"), Some(2.0));
        assert!(parse_float("NaN").unwrap().is_nan());
        assert_eq!(parse_float("-Inf"), Some(f64::NEG_INFINITY));
        assert_eq!(parse_float("0b1"), None);
        assert_eq!(parse_float(""), None);
    }
}
